"use client";

import { useEffect, useRef } from "react";
import Image from "next/image";
import { cn } from "@/lib/utils";
import { SWIVEL_EVENT } from "@/lib/brand-motion";

// Owner: D. The SeatSafe logo mark (pink → orange → red ticket with a white check). Source: public/logo.png;
// public/logo-mark.png is the trimmed UI copy and the app icons are generated by scripts/make-icons.mjs.
// Set the height with className (e.g. "h-6"); the width follows the 360×224 aspect ratio.
// `swivel`: the ticket spins once around its vertical axis on mount and whenever swivelLogo() fires
// (a page opens, a purchase lands). Skipped under prefers-reduced-motion.

export function BrandMark({ className, priority = false, swivel = false }: { className?: string; priority?: boolean; swivel?: boolean }) {
  const ref = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (!swivel) return;
    const el = ref.current;
    if (!el) return;
    const spin = () => {
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      if (el.getAnimations().some((a) => a.playState === "running")) return; // already spinning
      el.animate(
        [
          { transform: "perspective(320px) rotateY(0deg) scale(1)" },
          { transform: "perspective(320px) rotateY(200deg) scale(1.18)", offset: 0.55 },
          { transform: "perspective(320px) rotateY(360deg) scale(1)" },
        ],
        { duration: 950, easing: "cubic-bezier(0.22, 1, 0.36, 1)" },
      );
    };
    spin();
    window.addEventListener(SWIVEL_EVENT, spin);
    return () => window.removeEventListener(SWIVEL_EVENT, spin);
  }, [swivel]);

  return (
    <span ref={ref} className="inline-flex shrink-0 will-change-transform">
      <Image
        src="/logo-mark.png"
        alt=""
        aria-hidden
        width={360}
        height={224}
        priority={priority}
        className={cn("h-6 w-auto select-none", className)}
        draggable={false}
      />
    </span>
  );
}
